; Pop-up keyboard reader: polls 64h/60h directly (redrawing the clock while idle), treats E0h as a prefix (40:B6 bit 7), maps extended scancodes (setup_extended_scancodes) to AL=0/AH=scancode, digit keys 02h-0Bh to '1'..'0', Backspace to 08h; unknown keys beep (setup_key_default).
popup_read_key:
        push cx                                  ; 1539
        push di                                  ; 153A
        push es                                  ; 153B

loc_153C:
        in al, 0x64                              ; 153C  port 64h: KBC command/status
        test al, 1                               ; 153E
        jne short loc_1550                       ; 1540
        mov al, 0xc                              ; 1542
        db 0xE8, 0xC8, 0x25                      ; 1544  call cmos_hw_read
        test al, 0x10                            ; 1547
        je short loc_153C                        ; 1549
        db 0xE8, 0xFF, 0x25                      ; 154B  call setup_draw_time_date
        jmp short loc_153C                       ; 154E

loc_1550:
        in al, 0x60                              ; 1550  port 60h: KBC data
        cmp al, 0xe0                             ; 1552
        jne short loc_1566                       ; 1554
        push ax                                  ; 1556
        push ds                                  ; 1557
        mov ax, 0x40                             ; 1558
        mov ds, ax                               ; 155B
        or byte [bda.phoenix_flags2], 0x80       ; 155D  bda.phoenix_flags2
        pop ds                                   ; 1562
        pop ax                                   ; 1563
        jmp short loc_153C                       ; 1564

loc_1566:
        db 0x0A, 0xC0                            ; 1566  or al, al
        js short loc_153C                        ; 1568
        push bx                                  ; 156A
        mov bx, cs                               ; 156B
        mov es, bx                               ; 156D
        pop bx                                   ; 156F
        mov cx, 0xe                              ; 1570
        mov di, 0x15e9                           ; 1573
        repne scasb                              ; 1576
        je short loc_15A5                        ; 1578
        mov cx, 7                                ; 157A
        mov di, 0x15f7                           ; 157D
        repne scasb                              ; 1580
        je short loc_15DC                        ; 1582
        cmp al, 2                                ; 1584
        jl short loc_159C                        ; 1586
        cmp al, 0xb                              ; 1588
        ja short loc_159C                        ; 158A
        db 0x8A, 0xE0                            ; 158C  mov ah, al
        cmp al, 0xb                              ; 158E
        jne short loc_1596                       ; 1590
        mov al, 0x30                             ; 1592
        jmp short loc_15E5                       ; 1594

loc_1596:
        dec al                                   ; 1596
        add al, 0x30                             ; 1598
        jmp short loc_15E5                       ; 159A

loc_159C:
        cmp al, 0x2a                             ; 159C
        je short loc_153C                        ; 159E
        call setup_key_default                   ; 15A0
        jmp short loc_153C                       ; 15A3

loc_15A5:
        push ax                                  ; 15A5
        push ds                                  ; 15A6
        mov ax, 0x40                             ; 15A7
        mov ds, ax                               ; 15AA
        test byte [bda.phoenix_flags2], 0x80     ; 15AC  bda.phoenix_flags2
        jne short loc_15CF                       ; 15B1
        test byte [bda.kbd_flags1], 0x20         ; 15B3  bda.kbd_flags1
        je short loc_15CF                        ; 15B8
        cmp al, 0x3f                             ; 15BA
        je short loc_15CF                        ; 15BC
        cmp al, 0x40                             ; 15BE
        je short loc_15CF                        ; 15C0
        and byte [bda.phoenix_flags2], 0x7f      ; 15C2  bda.phoenix_flags2
        pop ds                                   ; 15C7
        pop ax                                   ; 15C8
        call setup_key_default                   ; 15C9
        jmp near loc_153C                        ; 15CC

loc_15CF:
        and byte [0xb6], 0x7f                    ; 15CF  bda.phoenix_flags2?
        pop ds                                   ; 15D4
        pop ax                                   ; 15D5
        db 0x8A, 0xE0                            ; 15D6  mov ah, al
        mov al, 0                                ; 15D8
        jmp short loc_15E5                       ; 15DA

loc_15DC:
        db 0x8A, 0xE0                            ; 15DC  mov ah, al
        cmp ah, 0xe                              ; 15DE
        jne short loc_15E5                       ; 15E1
        mov al, 8                                ; 15E3

loc_15E5:
        pop es                                   ; 15E5
        pop di                                   ; 15E6
        pop cx                                   ; 15E7
        ret                                      ; 15E8

