setup_extended_scancodes:
; [data] setup_extended_scancodes
        db 0x48, 0x4B, 0x4D, 0x50, 0x3B, 0x3C, 0x3F, 0x40, 0x45, 0x52, 0x53, 0x3E, 0x49, 0x51, 0x01, 0x39 ; 15E9 HKMP;<?@ERS>IQ.9
        db 0x4E, 0x4A, 0x0C, 0x0D, 0x0E ; 15F9 NJ...

; ZF clear when 40:B6 bit 1 is set - SETUP was started as PhoenixMISER's pop-up (bda_popup_mark_set); keyboard then comes straight from the KBC (popup_read_key) instead of INT 16h.
setup_in_popup:
        push ax                                  ; 15FE
        push ds                                  ; 15FF
        mov ax, 0x40                             ; 1600
        mov ds, ax                               ; 1603
        test byte [bda.phoenix_flags2], 2        ; 1605  bda.phoenix_flags2
        pop ds                                   ; 160A
        pop ax                                   ; 160B
        ret                                      ; 160C

; Derives a bit mask from CX (video ROM size in 32 KB units, video_rom_size_32k_units) and updates CMOS 48h in the shadow (shadow-RAM configuration, best guess), then redraws the following fields.
setup_shadow_cmos48_update:
        call video_rom_size_32k_units            ; 160D
        cmp cx, 0                                ; 1610
        jne short loc_1616                       ; 1613
        inc cx                                   ; 1615

loc_1616:
        db 0x8A, 0xF8                            ; 1616  mov bh, al
        mov al, 0x48                             ; 1618
        db 0xE8, 0x12, 0x25                      ; 161A  call cmos_shadow_read
        mov bl, 1                                ; 161D
        shl bl, cl                               ; 161F
        dec bl                                   ; 1621
        not bl                                   ; 1623
        db 0x22, 0xC3                            ; 1625  and al, bl

; Continuation: BH bit 0 selects set/clear, writes CMOS 48h, setup_redraw_following_fields, setup_ext_checksum_to_shadow.
setup_shadow_cmos48_tail:
        and bh, 1                                ; 1627
        je short loc_1630                        ; 162A
        not bl                                   ; 162C
        db 0x0A, 0xC3                            ; 162E  or al, bl

loc_1630:
        db 0x8A, 0xF8                            ; 1630  mov bh, al
        mov al, 0x48                             ; 1632
        db 0xE8, 0x07, 0x25                      ; 1634  call cmos_shadow_write
        call setup_redraw_following_fields       ; 1637
        db 0xE8, 0x73, 0x22                      ; 163A  call setup_ext_checksum_to_shadow
        ret                                      ; 163D

; ES := C000h then option_rom_size_at_es.
video_rom_size_32k_units:
        push es                                  ; 163E
        mov bx, 0xc000                           ; 163F
        mov es, bx                               ; 1642

; CX := 0 when ES:0000 is not 55AAh, else rom_size_from_header.
option_rom_size_at_es:
        mov bx, 0                                ; 1644
        mov bx, word [es:bx]                     ; 1647
        cmp bx, 0xaa55                           ; 164A
        je short rom_size_from_header            ; 164E
        mov cx, 0                                ; 1650
        pop es                                   ; 1653
        ret                                      ; 1654

; CX := ES:[2] (512-byte units) / 64 rounded up = size in 32 KB blocks.
rom_size_from_header:
        mov bx, 2                                ; 1655
        mov cl, byte [es:bx]                     ; 1658
        db 0x32, 0xED                            ; 165B  xor ch, ch
        db 0x8B, 0xD9                            ; 165D  mov bx, cx
        shr cx, 5                                ; 165F
        and bx, 0x1f                             ; 1662
        cmp bx, 0                                ; 1665
        je short loc_166D                        ; 1668
        add cx, 1                                ; 166A

loc_166D:
        pop es                                   ; 166D
        ret                                      ; 166E

; Unless [bp+2E] bit 1: redraws the next CX-1 field records (handler +6 and setup_draw_field).
setup_redraw_following_fields:
        test byte [bp + setup_frame.flags], 2    ; 166F  setup_frame.flags
        jne short loc_1690                       ; 1673
        cmp cx, 1                                ; 1675
        jle short loc_1690                       ; 1678
        dec cx                                   ; 167A
        push cx                                  ; 167B

loc_167C:
        push cx                                  ; 167C
        inc byte [bp + setup_frame.field_index]  ; 167D  setup_frame.field_index
        db 0xE8, 0xBA, 0x0D                      ; 1680  call setup_field_record
        call setup_field_handler_6               ; 1683
        call setup_draw_field                    ; 1686
        pop cx                                   ; 1689
        loop loc_167C                            ; 168A
        pop cx                                   ; 168C
        sub byte [bp + setup_frame.field_index], cl ; 168D  setup_frame.field_index

loc_1690:
        ret                                      ; 1690

; Words 0Ch, 0..5 (field index table, best guess) followed by a 4-byte stub.
setup_word_table_1691:
; [data] setup_word_table_1691
        db 0x0C, 0x00, 0x00, 0x00, 0x01, 0x00, 0x02, 0x00, 0x03, 0x00, 0x04, 0x00, 0x05, 0x00, 0xE8, 0x01 ; 1691 ................
