        cmp dh, 1                                ; 3D94
        jg short loc_3D9D                        ; 3D97
        mov dh, 0x12                             ; 3D99
        jmp short loc_3DB7                       ; 3D9B

loc_3D9D:
        db 0x8A, 0xE6                            ; 3D9D  mov ah, dh
        db 0x8A, 0xC6                            ; 3D9F  mov al, dh
        and al, 0xf                              ; 3DA1
        shr ah, 4                                ; 3DA3
        dec al                                   ; 3DA6
        aas                                      ; 3DA8
        shl ah, 4                                ; 3DA9
        db 0x8A, 0xF0                            ; 3DAC  mov dh, al
        db 0x02, 0xF4                            ; 3DAE  add dh, ah
        cmp dh, 0x13                             ; 3DB0
        jl short loc_3DB7                        ; 3DB3
        mov dh, 1                                ; 3DB5

loc_3DB7:
        call days_in_month_lookup                ; 3DB7
        mov bh, 0xa                              ; 3DBA
        db 0x8A, 0xC3                            ; 3DBC  mov al, bl
        div bh                                   ; 3DBE
        shl al, 4                                ; 3DC0
        db 0x0A, 0xC4                            ; 3DC3  or al, ah
        db 0x3A, 0xD0                            ; 3DC5  cmp dl, al
        jle short loc_3DCB                       ; 3DC7
        db 0x8A, 0xD0                            ; 3DC9  mov dl, al

loc_3DCB:
        call rtc_write_date                      ; 3DCB
        call rtc_status_regs_fix                 ; 3DCE
        ret                                      ; 3DD1

; Day +: wraps at the month length (leap years honoured).
date_day_inc:
        call rtc_read_date                       ; 3DD2
        call days_in_month_lookup                ; 3DD5
        db 0x8A, 0xC3                            ; 3DD8  mov al, bl
        mov bl, 0xa                              ; 3DDA
        div bl                                   ; 3DDC
        shl al, 4                                ; 3DDE
        db 0x02, 0xC4                            ; 3DE1  add al, ah
        db 0x8A, 0xD8                            ; 3DE3  mov bl, al
        db 0x8A, 0xE2                            ; 3DE5  mov ah, dl
        db 0x8A, 0xC2                            ; 3DE7  mov al, dl
        and al, 0xf                              ; 3DE9
        shr ah, 4                                ; 3DEB
        inc al                                   ; 3DEE
        aaa                                      ; 3DF0
        shl ah, 4                                ; 3DF1
        db 0x8A, 0xD0                            ; 3DF4  mov dl, al
        db 0x02, 0xD4                            ; 3DF6  add dl, ah
        db 0x3A, 0xD3                            ; 3DF8  cmp dl, bl
        jle short loc_3DFE                       ; 3DFA
        mov dl, 1                                ; 3DFC

loc_3DFE:
        call rtc_write_date                      ; 3DFE
        call rtc_status_regs_fix                 ; 3E01
        ret                                      ; 3E04

; Day -: 1 -> month length.
date_day_dec:
        call rtc_read_date                       ; 3E05
        call days_in_month_lookup                ; 3E08
        db 0x8A, 0xC3                            ; 3E0B  mov al, bl
        mov bl, 0xa                              ; 3E0D
        div bl                                   ; 3E0F
        shl al, 4                                ; 3E11
        db 0x02, 0xC4                            ; 3E14  add al, ah
        db 0x8A, 0xD8                            ; 3E16  mov bl, al
        cmp dl, 1                                ; 3E18
        jg short loc_3E21                        ; 3E1B
        db 0x8A, 0xD3                            ; 3E1D  mov dl, bl
        jmp short loc_3E34                       ; 3E1F

loc_3E21:
        db 0x8A, 0xE2                            ; 3E21  mov ah, dl
        db 0x8A, 0xC2                            ; 3E23  mov al, dl
        and al, 0xf                              ; 3E25
        shr ah, 4                                ; 3E27
        dec al                                   ; 3E2A
        aas                                      ; 3E2C
        shl ah, 4                                ; 3E2D
        db 0x8A, 0xD0                            ; 3E30  mov dl, al
