loc_3E34:
        call rtc_write_date                      ; 3E34
        call rtc_status_regs_fix                 ; 3E37
        ret                                      ; 3E3A

; Year 99 rolls over to century 20h.
date_year_inc:
        call rtc_read_date                       ; 3E3B
        db 0x8A, 0xE1                            ; 3E3E  mov ah, cl
        db 0x8A, 0xC1                            ; 3E40  mov al, cl
        and al, 0xf                              ; 3E42
        shr ah, 4                                ; 3E44
        inc al                                   ; 3E47
        aaa                                      ; 3E49
        shl ah, 4                                ; 3E4A
        db 0x8A, 0xC8                            ; 3E4D  mov cl, al
        db 0x02, 0xCC                            ; 3E4F  add cl, ah
        cmp cl, 0x99                             ; 3E51
        jbe short loc_3E65                       ; 3E54
        cmp ch, 0x19                             ; 3E56
        jne short loc_3E61                       ; 3E59
        mov ch, 0x20                             ; 3E5B
        db 0x32, 0xC9                            ; 3E5D  xor cl, cl
        jmp short loc_3E65                       ; 3E5F

loc_3E61:
        mov ch, 0x19                             ; 3E61
        mov cl, 0x80                             ; 3E63

loc_3E65:
        db 0x8A, 0xE5                            ; 3E65  mov ah, ch
        and ah, 3                                ; 3E67
        cmp ah, 1                                ; 3E6A
        jne short loc_3E7B                       ; 3E6D
        cmp dh, 2                                ; 3E6F
        jne short loc_3E7B                       ; 3E72
        cmp dl, 0x29                             ; 3E74
        jne short loc_3E7B                       ; 3E77
        dec dl                                   ; 3E79

loc_3E7B:
        call rtc_write_date                      ; 3E7B
        call rtc_status_regs_fix                 ; 3E7E
        push bx                                  ; 3E81
        db 0x8A, 0xFD                            ; 3E82  mov bh, ch
        mov al, 0x32                             ; 3E84
        call cmos_shadow_write                   ; 3E86
        pop bx                                   ; 3E89
        ret                                      ; 3E8A

; Year -: 00 of century 20h -> 99 of 19h; 1980-style floor at 80 of 19h; February 29 clamped.
date_year_dec:
        call rtc_read_date                       ; 3E8B
        cmp ch, 0x19                             ; 3E8E
        jne short loc_3E9E                       ; 3E91
        cmp cl, 0x80                             ; 3E93
        jne short loc_3EA9                       ; 3E96
        mov ch, 0x20                             ; 3E98
        mov cl, 0x99                             ; 3E9A
        jmp short loc_3EBC                       ; 3E9C

loc_3E9E:
        cmp cl, 0                                ; 3E9E
        jne short loc_3EA9                       ; 3EA1
        mov ch, 0x19                             ; 3EA3
        mov cl, 0x99                             ; 3EA5
        jmp short loc_3EBC                       ; 3EA7

loc_3EA9:
        db 0x8A, 0xE1                            ; 3EA9  mov ah, cl
        db 0x8A, 0xC1                            ; 3EAB  mov al, cl
        and al, 0xf                              ; 3EAD
        shr ah, 4                                ; 3EAF
        dec al                                   ; 3EB2
        aas                                      ; 3EB4
        shl ah, 4                                ; 3EB5
        db 0x8A, 0xC8                            ; 3EB8  mov cl, al
        db 0x02, 0xCC                            ; 3EBA  add cl, ah

loc_3EBC:
        db 0x8A, 0xE5                            ; 3EBC  mov ah, ch
        and ah, 3                                ; 3EBE
        cmp ah, 1                                ; 3EC1
        jne short loc_3ED2                       ; 3EC4
        cmp dh, 2                                ; 3EC6
        jne short loc_3ED2                       ; 3EC9
        cmp dl, 0x29                             ; 3ECB
        jne short loc_3ED2                       ; 3ECE
        dec dl                                   ; 3ED0

loc_3ED2:
        call rtc_write_date                      ; 3ED2
        call rtc_status_regs_fix                 ; 3ED5
        push bx                                  ; 3ED8
        db 0x8A, 0xFD                            ; 3ED9  mov bh, ch
        mov al, 0x32                             ; 3EDB
        call cmos_shadow_write                   ; 3EDD
        pop bx                                   ; 3EE0
        ret                                      ; 3EE1

; BL := days of month DH (table 0C56h, +1 for February in a leap year CL).
days_in_month_lookup:
        push dx                                  ; 3EE2
        push si                                  ; 3EE3
        db 0x8A, 0xC6                            ; 3EE4  mov al, dh
        call bcd_to_binary                       ; 3EE6
        dec al                                   ; 3EE9
        db 0x32, 0xE4                            ; 3EEB  xor ah, ah
        mov si, 0xc56                            ; 3EED
        db 0x03, 0xF0                            ; 3EF0  add si, ax
        mov bl, byte [si]                        ; 3EF2
        db 0x3D, 0x01, 0x00                      ; 3EF4  cmp ax, 1
        jne short loc_3F07                       ; 3EF7
        db 0x8A, 0xC1                            ; 3EF9  mov al, cl
        call bcd_to_binary                       ; 3EFB
        db 0x32, 0xE4                            ; 3EFE  xor ah, ah
        test ax, 3                               ; 3F00
        jne short loc_3F07                       ; 3F03
        inc bl                                   ; 3F05

loc_3F07:
        pop si                                   ; 3F07
        pop dx                                   ; 3F08
        ret                                      ; 3F09

; BCD AL -> two ASCII digits in AL/AH.
bcd_to_ascii_pair:
        db 0x8A, 0xE0                            ; 3F0A  mov ah, al
        shr al, 4                                ; 3F0C
        add al, 0x30                             ; 3F0F
        and ah, 0xf                              ; 3F11
        add ah, 0x30                             ; 3F14
        ret                                      ; 3F17

; AL (0-99) -> two ASCII digits in AX.
byte_to_2digit_ascii:
        push cx                                  ; 3F18
        db 0x32, 0xE4                            ; 3F19  xor ah, ah
        mov cl, 0xa                              ; 3F1B
        div cl                                   ; 3F1D
        add ax, 0x3030                           ; 3F1F
        pop cx                                   ; 3F22
        ret                                      ; 3F23

; AX -> up to BX decimal digits written right-to-left at SS:DI.
itoa_right_aligned:
        push cx                                  ; 3F24
        push dx                                  ; 3F25
        mov cx, 0xa                              ; 3F26

loc_3F29:
        db 0x33, 0xD2                            ; 3F29  xor dx, dx
        idiv cx                                  ; 3F2B
        add dl, 0x30                             ; 3F2D
        mov byte [ss:di], dl                     ; 3F30
        dec bx                                   ; 3F33
        je short loc_3F3D                        ; 3F34
        dec di                                   ; 3F36
        db 0x3D, 0x00, 0x00                      ; 3F37  cmp ax, 0
        jne short loc_3F29                       ; 3F3A
        inc di                                   ; 3F3C

loc_3F3D:
        pop dx                                   ; 3F3D
        pop cx                                   ; 3F3E
        ret                                      ; 3F3F

; AL BCD -> binary.
bcd_to_binary:
        db 0x32, 0xE4                            ; 3F40  xor ah, ah
        db 0x8A, 0xD0                            ; 3F42  mov dl, al
        and dl, 0xf                              ; 3F44
        shr al, 4                                ; 3F47
        imul ax, ax, 0xa                         ; 3F4A
        db 0x02, 0xC2                            ; 3F4D  add al, dl
        ret                                      ; 3F4F

; AL -> two hex digits (AL low nibble in AL, high in AH) as ASCII. No caller found.
byte_to_hex_ascii:
        db 0x8A, 0xE0                            ; 3F50  mov ah, al
        and al, 0xf                              ; 3F52
        cmp al, 9                                ; 3F54
        jg short loc_3F5C                        ; 3F56
        add al, 0x30                             ; 3F58
        jmp short loc_3F5E                       ; 3F5A

loc_3F5C:
        add al, 0x37                             ; 3F5C

loc_3F5E:
        shr ah, 4                                ; 3F5E
        cmp ah, 9                                ; 3F61
        jg short loc_3F6B                        ; 3F64
        add ah, 0x30                             ; 3F66
        jmp short loc_3F6E                       ; 3F69

loc_3F6B:
        add ah, 0x37                             ; 3F6B

loc_3F6E:
        ret                                      ; 3F6E

; 'Rebooting...'
msg_rebooting:
; [data] msg_rebooting
        db 0x52, 0x65, 0x62, 0x6F, 0x6F, 0x74, 0x69, 0x6E, 0x67, 0x2E, 0x2E, 0x2E, 0x00 ; 3F6F Rebooting....

; Clears the screen (INT 10h scroll, 25x80), prints msg_rebooting, KBC D1h DFh (A20), FEh (pulse reset), HLT. Reached from setup_save_and_reboot (pop-up F4).
setup_reboot:
        db 0x33, 0xC9                            ; 3F7C  xor cx, cx
        mov dx, 0x184f                           ; 3F7E
        mov bh, 0xf                              ; 3F81
        mov al, 0                                ; 3F83
        mov ah, 6                                ; 3F85
        pusha                                    ; 3F87
        int 0x10                                 ; 3F88  video
        popa                                     ; 3F8A
        mov bl, 7                                ; 3F8B
        mov dx, 0x107                            ; 3F8D
        mov si, 0x3f6f                           ; 3F90
        push es                                  ; 3F93
        push cs                                  ; 3F94
        pop es                                   ; 3F95
        db 0xE8, 0x0F, 0xE2                      ; 3F96  call setup_print_at
        pop es                                   ; 3F99
        call kbc_wait_input_empty_setup          ; 3F9A
        mov al, 0xd1                             ; 3F9D
        out 0x64, al                             ; 3F9F  port 64h: KBC command/status
        call kbc_wait_input_empty_setup          ; 3FA1
        mov al, 0xdf                             ; 3FA4
        out 0x60, al                             ; 3FA6  port 60h: KBC data
        call kbc_wait_input_empty_setup          ; 3FA8
        cli                                      ; 3FAB
        mov al, 0xfe                             ; 3FAC
        out 0x64, al                             ; 3FAE  port 64h: KBC command/status

loc_3FB0:
        hlt                                      ; 3FB0
        jmp short loc_3FB0                       ; 3FB1

; Spin until 64h bit 1 clears (used by setup_reboot).
kbc_wait_input_empty_setup:
        mov dx, 0x64                             ; 3FB3

loc_3FB6:
        in al, dx                                ; 3FB6
        test al, 2                               ; 3FB7
        jne short loc_3FB6                       ; 3FB9
        ret                                      ; 3FBB
; [data] FFh fill (end of the SETUP segment)
; ---------------------------------------------------------------------------------------------
; (patched) Extended option-ROM scan: the original C800h-DFFFh pass, then EE00h-EFFFh where the
; XTIDE Universal BIOS option ROM is embedded (image offset 0E000h).  scan_option_roms checks the
; 55AAh signature and the 8-bit checksum before far-calling the init entry at +3.
post_scan_option_roms_ext:
        mov si, 0xc800
        mov cx, 0xe000
        call scan_option_roms
        call xtide_apply_cmos_config
        mov si, 0xee00
        mov cx, 0xf000
        call scan_option_roms
        ret

; ---------------------------------------------------------------------------------------------
; (patched) Apply the SETUP page-3 values (CMOS 60h/61h) to the XTIDE ROMVARS in the shadow-RAM
; copy of the option ROM at EE00:0000.  POST 53h shadows E0000-EFFFF in 16 KB blocks (chipset reg
; 200h bits 8-11); reg 207h bit 11 write-enables the EC000-EFFFF block while the bytes are patched.
; The option-ROM checksum byte at EE00:1FFF is recomputed so scan_option_roms accepts the image.
; CMOS 60h: bit0 custom, bit1 two controllers, bits2-3 boot drive, bit4 block mode off, bits5-6 write cache
; CMOS 61h: bits0-1 master translation, bits2-3 slave translation, bits4-6 standby timer
xtide_apply_cmos_config:
        pusha
        push ds
        push es
        mov al, 0x60
        call cmos_read
        test al, 1
        jz .done                                ; 'BIOS Default': leave the ROM as built
        mov bl, al
        mov al, 0x61
        call cmos_read
        mov bh, al
        mov ax, 0xee00
        mov es, ax
        cmp word [es:0], 0xaa55
        jne .done
        cmp word [es:6], 'XU'                   ; ROMVARS.rgbSign = 'XUB212'
        jne .done
        cmp word [es:8], 'B2'
        jne .done
        mov dx, 0x24                            ; reg 207h |= 0800h (write enable EC000-EFFFF shadow)
        mov ax, 0x207
        out dx, ax
        out 0xed, al
        mov dx, 0x26
        in ax, dx
        push ax                                 ; original 207h
        or ah, 0x08
        push ax
        mov dx, 0x24
        mov ax, 0x207
        out dx, ax
        out 0xed, al
        pop ax
        mov dx, 0x26
        out dx, ax
        ; --- controllers
        mov al, 1
        test bl, 0x02
        jz .one_ctrl
        inc al
.one_ctrl:
        mov [es:72], al                          ; ROMVARS.bIdeCnt
        ; --- boot drive
        mov al, bl
        shr al, 2
        and al, 3
        mov si, xt_boot_drive_tab
        call .lookup
        mov [es:73], al                          ; ROMVARS.bBootDrv
        ; --- standby timer
        mov al, bh
        shr al, 4
        and al, 7
        mov si, xt_standby_tab
        call .lookup
        mov [es:76], al                          ; ROMVARS.bIdleTimeout
        ; --- master drive flags: bits0-1 write cache, bits2-3 translation, bit4 block mode
        mov al, bh
        and al, 3
        mov si, xt_translate_tab
        call .lookup
        mov cl, al
        call .common_flags
        mov al, [es:84]
        and al, 0xe0
        or al, cl
        mov [es:84], al                          ; ideVars0.drvParamsMaster.wFlags (low byte)
        ; --- slave drive flags
        mov al, bh
        shr al, 2
        and al, 3
        mov si, xt_translate_tab
        call .lookup
        mov cl, al
        call .common_flags
        mov al, [es:90]
        and al, 0xe0
        or al, cl
        mov [es:90], al                          ; ideVars0.drvParamsSlave.wFlags (low byte)
        ; --- option-ROM checksum byte
        xor si, si
        xor al, al
        mov cx, 0x1fff
.sum:
        add al, [es:si]
        inc si
        loop .sum
        neg al
        mov [es:0x1fff], al
        pop ax                                  ; restore reg 207h
        push ax
        mov dx, 0x24
        mov ax, 0x207
        out dx, ax
        out 0xed, al
        pop ax
        mov dx, 0x26
        out dx, ax
.done:
        pop es
        pop ds
        popa
        ret
.lookup:                                        ; AL := [cs:si + AL]
        xor ah, ah
        add si, ax
        mov al, [cs:si]
        ret
.common_flags:                                  ; CL |= translation<<2 | block mode | write cache from BL
        shl cl, 2
        test bl, 0x10
        jnz .no_block
        or cl, 0x10                             ; FLG_DRVPARAMS_BLOCKMODE
.no_block:
        mov al, bl
        shr al, 5
        and al, 3
        mov si, xt_cache_tab
        call .lookup
        or cl, al
        ret
xt_boot_drive_tab:  db 0x80, 0x81, 0x00, 0x80
xt_standby_tab:     db 0, 12, 60, 120, 240, 0, 0, 0      ; ATA standby units of 5 s
xt_translate_tab:   db 3, 0, 1, 2                        ; Auto, CHS(normal), LARGE, assisted LBA
xt_cache_tab:       db 1, 0, 2, 1                        ; DISABLE, DEFAULT, ENABLE, (DISABLE)

; ---------------------------------------------------------------------------------------------
; (patched) Third SETUP page: XTIDE Hard Disk Setup.  Same record format as pages 1-2 (see docs/05):
; +0 row, +1 col, +2 value strings, +4 next, +6 load-from-CMOS, +8/+E key handlers, +A common,
; +C previous, +10 store-to-CMOS, +12 checksum update, +14 CMOS index, +15 mask, +16 max, +18 shift,
; +19 default, +1A/+1C secondary handlers, +1E type, +1F kind 66h (option list).
xt_page_counts:     db 0x13, 0x05, 7                    ; last field index per page
xt_page_values:     dw 0x00E5, 0x00F9, 0x0100            ; value arrays (frame offsets)
xt_page_records:    dw 0x014C, 0x1874, xt_rec_0          ; record arrays
xt_page_descriptors:
        db 0x1D, 0x04, 0x27, 0x0A, 0x69, 0x0A, 0x0E, 0x04, 0x06, 0x2C, 0x0B, 0x0E, 0x2A, 0x06, 0x1B, 0x05, 0x4C, 0x11, 0x8F, 0x11, 0x08, 0x04, 0x07, 0x83, 0x12, 0x00, 0x00, 0x00 ; pages 1-2, copied from 03D6
        dw 0x0519, xt_title                       ; title row/col, string
        dw xt_labels
        db 8
        dw 0x0704                                 ; label block row/col
        dw xt_help
        db 12
        dw 0x072F                                 ; help block row/col
xt_rec_0:                                      ; XTIDE Settings
        db 7, 31
        dw xt_str_0
        dw list_field_next_value, list_field_load_from_cmos, setup_key_default, setup_field_common
        dw list_field_prev_value, setup_key_default, list_field_write_cmos, setup_ext_checksum_to_shadow
        db 0x60, 0x01
        dw 1
        db 0, 0
        dw setup_nop_handler, setup_nop_handler
        db 0x00, 0x66
xt_rec_1:                                      ; IDE Controllers
        db 8, 31
        dw xt_str_1
        dw list_field_next_value, list_field_load_from_cmos, setup_key_default, setup_field_common
        dw list_field_prev_value, setup_key_default, list_field_write_cmos, setup_ext_checksum_to_shadow
        db 0x60, 0x02
        dw 1
        db 1, 0
        dw setup_nop_handler, setup_nop_handler
        db 0x00, 0x66
xt_rec_2:                                      ; Default Boot Drive
        db 9, 31
        dw xt_str_2
        dw list_field_next_value, list_field_load_from_cmos, setup_key_default, setup_field_common
        dw list_field_prev_value, setup_key_default, list_field_write_cmos, setup_ext_checksum_to_shadow
        db 0x60, 0x0C
        dw 2
        db 2, 0
        dw setup_nop_handler, setup_nop_handler
        db 0x00, 0x66
xt_rec_3:                                      ; Block Mode Transfers
        db 10, 31
        dw xt_str_3
        dw list_field_next_value, list_field_load_from_cmos, setup_key_default, setup_field_common
        dw list_field_prev_value, setup_key_default, list_field_write_cmos, setup_ext_checksum_to_shadow
        db 0x60, 0x10
        dw 1
        db 4, 0
        dw setup_nop_handler, setup_nop_handler
        db 0x00, 0x66
xt_rec_4:                                      ; Drive Write Cache
        db 11, 31
        dw xt_str_4
        dw list_field_next_value, list_field_load_from_cmos, setup_key_default, setup_field_common
        dw list_field_prev_value, setup_key_default, list_field_write_cmos, setup_ext_checksum_to_shadow
        db 0x60, 0x60
        dw 2
        db 5, 0
        dw setup_nop_handler, setup_nop_handler
        db 0x00, 0x66
xt_rec_5:                                      ; Master Translation
        db 12, 31
        dw xt_str_5
        dw list_field_next_value, list_field_load_from_cmos, setup_key_default, setup_field_common
        dw list_field_prev_value, setup_key_default, list_field_write_cmos, setup_ext_checksum_to_shadow
        db 0x61, 0x03
        dw 3
        db 0, 0
        dw setup_nop_handler, setup_nop_handler
        db 0x00, 0x66
xt_rec_6:                                      ; Slave Translation
        db 13, 31
        dw xt_str_6
        dw list_field_next_value, list_field_load_from_cmos, setup_key_default, setup_field_common
        dw list_field_prev_value, setup_key_default, list_field_write_cmos, setup_ext_checksum_to_shadow
        db 0x61, 0x0C
        dw 3
        db 2, 0
        dw setup_nop_handler, setup_nop_handler
        db 0x00, 0x66
xt_rec_7:                                      ; Drive Standby Timer
        db 14, 31
        dw xt_str_7
        dw list_field_next_value, list_field_load_from_cmos, setup_key_default, setup_field_common
        dw list_field_prev_value, setup_key_default, list_field_write_cmos, setup_ext_checksum_to_shadow
        db 0x61, 0x70
        dw 4
        db 4, 0
