xt_setup_init_pages_2_3:                        ; (patched) replaces the page-2 init at 1F50
        mov byte [bp + setup_frame.page], 1
        call setup_select_page
        mov byte [bp + setup_frame.field_index], 0
        mov cx, 6
        call setup_init_fields_range
        mov byte [bp + setup_frame.page], 2
        call setup_select_page
        mov byte [bp + setup_frame.field_index], 0
        mov cx, 8
        call setup_init_fields_range
        ret

        times (0x5800 - ($ - $$)) db 0xFF     ; re-pad to the start of the core segment

; 'Copyright 1985-1992  Phoenix Technologies Ltd.' at the start of the core segment (checksummed by the anti-tamper check).
core_copyright_string:
; [data] string
        db 0x43, 0x6F, 0x70, 0x79, 0x72, 0x69, 0x67, 0x68, 0x74, 0x20, 0x31, 0x39, 0x38, 0x35, 0x2D, 0x31 ; 5800 Copyright 1985-1
        db 0x39, 0x39, 0x32, 0x20, 0x20, 0x50, 0x68, 0x6F, 0x65, 0x6E, 0x69, 0x78, 0x20, 0x54, 0x65, 0x63 ; 5810 992  Phoenix Tec
        db 0x68, 0x6E, 0x6F, 0x6C, 0x6F, 0x67, 0x69, 0x65, 0x73, 0x20, 0x4C, 0x74, 0x64, 0x2E ; 5820 hnologies Ltd.

; AL = POST code. Writes it to port 80h; depending on ROM option flags at AF45 either halts (bit1), restarts POST (bit0), or sounds the beep code (5873) and halts.
post_fatal_error:
        out 0x80, al                             ; 582E  port 80h: POST diagnostic code
        test byte [cs:0xaf45], 2                 ; 5830
        je short loc_583B                        ; 5836
        cli                                      ; 5838
        hlt                                      ; 5839
        hlt                                      ; 583A

loc_583B:
        test byte [cs:0xaf45], 1                 ; 583B
        je short loc_5846                        ; 5841
        jmp near loc_58EE                        ; 5843

loc_5846:
        jmp short beep_code_and_halt             ; 5846

; Delay loop by watching PIT channel 2 count down (CX iterations).
beep_delay_pit2:
        mov al, 0x80                             ; 5848
        out 0x43, al                             ; 584A  port 43h: PIT control
        out 0xed, al                             ; 584C
        in al, 0x42                              ; 584E  port 42h: PIT ch2 (speaker)
        db 0x8A, 0xE0                            ; 5850  mov ah, al
        out 0xed, al                             ; 5852
        in al, 0x42                              ; 5854  port 42h: PIT ch2 (speaker)
        xchg al, ah                              ; 5856
        db 0x8B, 0xD0                            ; 5858  mov dx, ax

loc_585A:
        mov al, 0x80                             ; 585A
        out 0x43, al                             ; 585C  port 43h: PIT control
        out 0xed, al                             ; 585E
        in al, 0x42                              ; 5860  port 42h: PIT ch2 (speaker)
        db 0x8A, 0xE0                            ; 5862  mov ah, al
        out 0xed, al                             ; 5864
        in al, 0x42                              ; 5866  port 42h: PIT ch2 (speaker)
        xchg al, ah                              ; 5868
        db 0x3B, 0xD0                            ; 586A  cmp dx, ax
        db 0x8B, 0xD0                            ; 586C  mov dx, ax
        ja short loc_585A                        ; 586E
        loop loc_585A                            ; 5870
        ret                                      ; 5872

; Sounds the failing POST code on the speaker: PIT ch2 tone (43h=B6h, 42h=04A8h), number of beeps derived from the code (BH), then HLT. Uses ROM-stack returns at 58A5/58BA/58CD.
beep_code_and_halt:
        db 0x8A, 0xF8                            ; 5873  mov bh, al
        mov al, 0xb6                             ; 5875
        out 0x43, al                             ; 5877  port 43h: PIT control
        mov al, 0xa8                             ; 5879
        out 0x42, al                             ; 587B  port 42h: PIT ch2 (speaker)
        out 0xed, al                             ; 587D
        mov al, 4                                ; 587F
        out 0x42, al                             ; 5881  port 42h: PIT ch2 (speaker)
        mov bl, 3                                ; 5883
        shl bh, 2                                ; 5885
        mov ch, 0                                ; 5888
        db 0x8A, 0xCF                            ; 588A  mov cl, bh
        shr cx, 6                                ; 588C
        inc cx                                   ; 588F
        db 0x8B, 0xE9                            ; 5890  mov bp, cx
        mov cx, 0x190                            ; 5892
        in al, 0x61                              ; 5895  port 61h: port B (speaker/parity/refresh)
        or al, 3                                 ; 5897
        out 0x61, al                             ; 5899  port 61h: port B (speaker/parity/refresh)
        mov ax, cs                               ; 589B
        mov ss, ax                               ; 589D
        lea sp, [0x58a5]                         ; 589F
        jmp short beep_delay_pit2                ; 58A3
; [data] byte before post_kbc_reset_continue
        db 0xA7 ; 58A5 .

; Fragment after a POST step: speaker off (61h &= FDh), CX=200, ROM stack at 58BA, jump on.
post_kbc_reset_continue:
        pop ax                                   ; 58A6
        in al, 0x61                              ; 58A7  port 61h: port B (speaker/parity/refresh)
        and al, 0xfd                             ; 58A9
        out 0x61, al                             ; 58AB  port 61h: port B (speaker/parity/refresh)
        mov cx, 0xc8                             ; 58AD
        mov ax, cs                               ; 58B0
        mov ss, ax                               ; 58B2
        lea sp, [0x58ba]                         ; 58B4
        jmp short beep_delay_pit2                ; 58B8

; ROM-stack return words / continuation used by post_kbc_reset_continue.
post_kbc_reset_rom_stack:
; [data] post_kbc_reset_rom_stack
        db 0xBC, 0x58, 0x4D, 0x75, 0xD3, 0xB9, 0x20, 0x03, 0x8C, 0xC8, 0x8E, 0xD0, 0x8D, 0x26, 0xCD, 0x58 ; 58BA .XMu.. ......&.X
        db 0xE9, 0x7B, 0xFF, 0xCF, 0x58, 0xFE, 0xCB, 0x75, 0xB2, 0xE4, 0x61, 0x24, 0xFE, 0xE6, 0x61, 0xF4 ; 58CA .{..X..u..a$..a.

; First real POST code. SS := F000 (read from the reset vector), SP points at a ROM word = return address (Phoenix ROM-stack idiom).
post_start:
        mov ss, word [cs:0xfff3]                 ; 58DA
        mov sp, 0x58e5                           ; 58DF
        db 0xE9, 0x0C, 0x80                      ; 58E2  jmp post_stub_shl_edx

tbl_58E5:
; [data] ROM-stack return word 58E7
; [data] ROM stack word -> return address
        db 0xE7, 0x58 ; 58E5 .X

ret_58E7:
        mov cx, 0xfff0                           ; 58E7  -> reset_vector

loc_58EA:
        jmp short loc_58EC                       ; 58EA

loc_58EC:
        loop loc_58EA                            ; 58EC

loc_58EE:
        in ax, 0x8d                              ; 58EE
        jmp short loc_58F2                       ; 58F0

loc_58F2:
        cmp ax, 0x1234                           ; 58F2
        je near loc_5921                         ; 58F5
        cmp ax, 0x5678                           ; 58F9
        jne near post_cold_entry                 ; 58FC
        mov ax, 0x800                            ; 5900
        mov ss, ax                               ; 5903
        mov sp, 0                                ; 5905
        db 0xE8, 0xA2, 0x42                      ; 5908  call chipset_cfg_200_update
        db 0x33, 0xC0                            ; 590B  xor ax, ax
        out 0x8d, ax                             ; 590D
        db 0xE8, 0x9B, 0x42                      ; 590F  call chipset_cfg_200_update
        call hd_init                             ; 5912
        mov al, 0x22                             ; 5915
        out 0x80, al                             ; 5917  port 80h: POST diagnostic code
        mov ax, 0x5678                           ; 5919
        out 0x8d, ax                             ; 591C
        jmp short loc_5940                       ; 591E
; [data] alignment pad (nop / xchg bx,bx)
        db 0x90 ; 5920 .

loc_5921:
        cli                                      ; 5921
        mov ax, 0x300                            ; 5922
        out 0x24, ax                             ; 5925
        mov ax, 0x5e4                            ; 5927
        out 0x26, ax                             ; 592A
        mov ax, 0x200                            ; 592C
        out 0x24, ax                             ; 592F
        mov ax, 0                                ; 5931
        out 0x26, ax                             ; 5934
        mov ax, 0x207                            ; 5936
        out 0x24, ax                             ; 5939
        mov ax, 0                                ; 593B
        out 0x26, ax                             ; 593E

loc_5940:
        jmp 0xE800:0x10                          ; 5940  far jump outside module

; Cold/warm POST: NMI off, read chipset reg 1 (ports 24h/26h) bit 8 -> resume vector at 0040:0072; else read KBC status bit2 to pick CMOS 0Fh shutdown code.
post_cold_entry:
        cli                                      ; 5945
        mov al, 0x80                             ; 5946
        out 0xed, al                             ; 5948
        out 0x70, al                             ; 594A  port 70h: CMOS index / NMI enable
        cld                                      ; 594C
        mov ax, 1                                ; 594D
        out 0x24, ax                             ; 5950
        out 0xed, al                             ; 5952
        in ax, 0x26                              ; 5954
        out 0xed, al                             ; 5956
        test ax, 0x100                           ; 5958
        je short loc_596D                        ; 595B
        mov ax, 0x40                             ; 595D
        mov ds, ax                               ; 5960
        mov cx, 0x4000                           ; 5962

loc_5965:
        jmp short loc_5967                       ; 5965

loc_5967:
        loop loc_5965                            ; 5967
        db 0xFF, 0x2E, 0x72, 0x00                ; 5969  ljmp [0x72] ; far jump outside module; bda.reset_flag?

loc_596D:
        mov ah, 0                                ; 596D
        in al, 0x64                              ; 596F  port 64h: KBC command/status
        test al, 4                               ; 5971
        je near loc_5983                         ; 5973
        mov al, 0x8f                             ; 5977
        out 0x70, al                             ; 5979  port 70h: CMOS index / NMI enable
        out 0xed, al                             ; 597B
        in al, 0x71                              ; 597D  port 71h: CMOS data
        db 0x8A, 0xE0                            ; 597F  mov ah, al
        jmp short loc_598E                       ; 5981

loc_5983:
        mov ds, word [cs:0xd49f]                 ; 5983
        mov word [0x400 + bda.reset_flag], 0     ; 5988  bda.reset_flag

loc_598E:
        mov al, 0x8f                             ; 598E
        out 0x70, al                             ; 5990  port 70h: CMOS index / NMI enable
        mov al, 0                                ; 5992
        out 0xed, al                             ; 5994
        out 0x71, al                             ; 5996  port 71h: CMOS data
        cmp ah, 1                                ; 5998
        jne short loc_59A0                       ; 599B
        jmp near post_after_memsize              ; 599D

loc_59A0:
        cmp ah, 0xc                              ; 59A0
        ja near init_pics_and_fpu                ; 59A3
        cmp ah, 0xb                              ; 59A7
        je near init_pics_and_fpu                ; 59AA
        cmp ah, 6                                ; 59AE
        jae near post_shutdown_select            ; 59B1

; Reset FPU (port F1h); program PIC2 (ICW1=15h, ICW2=70h, ICW3=02h, ICW4=01h, mask FFh) and PIC1 (ICW1=15h, ICW2=08h, ICW3=04h, ICW4=01h, mask FBh).
init_pics_and_fpu:
        out 0xf1, al                             ; 59B5  port F1h: FPU reset
        mov dx, 0xa0                             ; 59B7
        mov al, 0x15                             ; 59BA
        out dx, al                               ; 59BC
        inc dx                                   ; 59BD
        mov al, 0x70                             ; 59BE
        out 0xed, al                             ; 59C0
        out dx, al                               ; 59C2
        mov al, 2                                ; 59C3
        out 0xed, al                             ; 59C5
        out dx, al                               ; 59C7
        mov al, 1                                ; 59C8
        out 0xed, al                             ; 59CA
        out dx, al                               ; 59CC
        mov al, 0xff                             ; 59CD
        out 0xed, al                             ; 59CF
        out dx, al                               ; 59D1
        mov dx, 0x20                             ; 59D2
        mov al, 0x15                             ; 59D5
        out 0xed, al                             ; 59D7
        out dx, al                               ; 59D9
        inc dx                                   ; 59DA
        mov al, 8                                ; 59DB
        out 0xed, al                             ; 59DD
        out dx, al                               ; 59DF
        mov al, 4                                ; 59E0
        out 0xed, al                             ; 59E2
        out dx, al                               ; 59E4
        mov al, 1                                ; 59E5
        out 0xed, al                             ; 59E7
        out dx, al                               ; 59E9
        mov al, 0xfb                             ; 59EA
        out 0xed, al                             ; 59EC
        out dx, al                               ; 59EE

; Temporary stack 0030:0080, DS=0. Shutdown code < 4 or > 0Ch -> normal boot path (5A92); else dispatch through shutdown_dispatch.
post_shutdown_select:
        mov bx, 0x30                             ; 59EF
        mov ss, bx                               ; 59F2
        mov sp, 0x80                             ; 59F4
        mov ds, word [cs:0xd49f]                 ; 59F7
        sub ah, 4                                ; 59FC
        jb short loc_5A06                        ; 59FF
        cmp ah, 8                                ; 5A01
        jbe short loc_5A09                       ; 5A04

loc_5A06:
