        out 0x64, al                             ; 6AEA  port 64h: KBC command/status
        db 0xE8, 0xCE, 0x28                      ; 6AEC  call kbc_wait_input_empty_cli

; Reset HD controller (3F6h bit2), floppy_detect_drives, set 40:10 floppy bits.
floppy_hd_reset_detect:
