        jne near loc_6BD5                        ; 6BAD
        db 0xE8, 0x55, 0x67                      ; 6BB1  call print_inline_msg
; [data] string
; [data] inline message for print_inline_msg
        db 0x4B, 0x65, 0x79, 0x62, 0x6F, 0x61, 0x72, 0x64, 0x20, 0x69, 0x73, 0x20, 0x6C, 0x6F, 0x63, 0x6B ; 6BB4 Keyboard is lock
        db 0x65, 0x64, 0x20, 0x2D, 0x20, 0x75, 0x6E, 0x6C, 0x6F, 0x63, 0x6B, 0x0D, 0x0A, 0x00 ; 6BC4 ed - unlock...
        db 0xE8, 0xE0, 0x68                      ; 6BD2  call set_post_error_flag

loc_6BD5:
        test byte [cs:0xaf46], 0x80              ; 6BD5
        je near config_error_check               ; 6BDB
        test byte [cs:0xaf46], 8                 ; 6BDF
        je near loc_6C01                         ; 6BE5
        test byte [cs:0xaf46], 0x10              ; 6BE9
