        je near loc_6C53                         ; 6C08
        db 0xE8, 0xFA, 0x66                      ; 6C0C  call print_inline_msg
; [data] string
; [data] inline message for print_inline_msg
        db 0x49, 0x6E, 0x76, 0x61, 0x6C, 0x69, 0x64, 0x20, 0x63, 0x6F, 0x6E, 0x66, 0x69, 0x67, 0x75, 0x72 ; 6C0F Invalid configur
        db 0x61, 0x74, 0x69, 0x6F, 0x6E, 0x20, 0x69, 0x6E, 0x66, 0x6F, 0x72, 0x6D, 0x61, 0x74, 0x69, 0x6F ; 6C1F ation informatio
        db 0x6E, 0x20, 0x2D, 0x20, 0x70, 0x6C, 0x65, 0x61, 0x73, 0x65, 0x20, 0x72, 0x75, 0x6E, 0x20, 0x53 ; 6C2F n - please run S
        db 0x45, 0x54, 0x55, 0x50, 0x20, 0x70, 0x72, 0x6F, 0x67, 0x72, 0x61, 0x6D, 0x0D, 0x0A, 0x00 ; 6C3F ETUP program...
        call prompt_f1_continue                  ; 6C4E
