        pop dx                                   ; 6CDC
        pop cx                                   ; 6CDD
        pop bx                                   ; 6CDE
        push ds                                  ; 6CDF
        db 0x33, 0xC0                            ; 6CE0  xor ax, ax
        mov ds, ax                               ; 6CE2
        mov al, byte [0x400 + bda.kbd_led_flags] ; 6CE4  bda.kbd_led_flags
        and al, 0xf8                             ; 6CE7
        mov byte [0x400 + bda.kbd_led_flags], al ; 6CE9  bda.kbd_led_flags
