; 'A486 Version 1.03'
str_version:
; [data] string
        db 0x41, 0x34, 0x38, 0x36, 0x20, 0x56, 0x65, 0x72, 0x73, 0x69, 0x6F, 0x6E, 0x20, 0x31, 0x2E, 0x30 ; D2E6 A486 Version 1.0
        db 0x33, 0x0D, 0x0A, 0x00 ; D2F6 3...

; Print string at SI, then value as hex, then h CR LF.
print_hex_value_h_crlf:
        db 0xE8, 0x6E, 0xE5                      ; D2FA  call print_string_cs_si
        call print_hex_byte                      ; D2FD
        call set_post_error_flag                 ; D300
        mov si, 0xd4b1                           ; D303
        db 0xE9, 0x62, 0xE5                      ; D306  jmp print_string_cs_si

; Prints the NUL-terminated message that follows the CALL instruction, then returns past it.
print_inline_msg:
        push bp                                  ; D309
        db 0x8B, 0xEC                            ; D30A  mov bp, sp
        push si                                  ; D30C
        pushf                                    ; D30D
        mov si, word [bp + 2]                    ; D30E
        db 0xE8, 0x57, 0xE5                      ; D311  call print_string_cs_si
        inc si                                   ; D314
        mov word [bp + 2], si                    ; D315
        popf                                     ; D318
        pop si                                   ; D319
        pop bp                                   ; D31A
        ret                                      ; D31B

; Print AX as 4 hex digits.
print_hex_word:
        xchg al, ah                              ; D31C
        call print_hex_byte                      ; D31E
        xchg al, ah                              ; D321

; Print AL as 2 hex digits.
print_hex_byte:
        push ax                                  ; D323
        push cx                                  ; D324
        pushf                                    ; D325
        mov cl, 4                                ; D326
        shr al, cl                               ; D328
        popf                                     ; D32A
        pop cx                                   ; D32B
        call print_hex_nibble                    ; D32C
        pop ax                                   ; D32F

; AL low nibble -> hex digit via print_char_al_int10.
print_hex_nibble:
        push ax                                  ; D330
        pushf                                    ; D331
        and al, 0xf                              ; D332
        add al, 0x90                             ; D334
        daa                                      ; D336
        adc al, 0x40                             ; D337
        daa                                      ; D339
        db 0xE8, 0x22, 0xE5                      ; D33A  call print_char_al_int10
        popf                                     ; D33D
        pop ax                                   ; D33E
        ret                                      ; D33F

; Wait for a key whose uppercase letter is in the list at CS:SI (D7D1 = 'RS'); AL = letter.
wait_key_from_list:
        db 0xE8, 0x28, 0xE5                      ; D340  call print_string_cs_si

; INT 16h AH=0, returns the key upper-cased in AL.
wait_key_upper:
        db 0x32, 0xE4                            ; D343  xor ah, ah
        int 0x16                                 ; D345  keyboard
        and al, 0x7f                             ; D347
        cmp al, 0x61                             ; D349
        jb short loc_D355                        ; D34B
        cmp al, 0x7a                             ; D34D
        ja near loc_D355                         ; D34F
        sub al, 0x20                             ; D353

loc_D355:
        ret                                      ; D355

; NMI: bump the POST code on port 80h, read port 61h (bit 7 RAM parity, bit 6 I/O channel check), disable both checks (61h |= 0Ch). With ROM option AF45 bit5 also check PIC2 ISR (0Bh) for an unexpected IRQ. Prints 'Memory parity' / 'I/O card parity' / 'Unexpected type 02' + ' interrupt at CS:IP', then 'Type (S)hut off NMI, (R)eboot': R -> post_entry, S -> leave the checks disabled and IRET.
int02_nmi_handler:
        push bp                                  ; D356
        db 0x8B, 0xEC                            ; D357  mov bp, sp
        push ax                                  ; D359
        push si                                  ; D35A
        call cmos_read_shutdown_nmi_off          ; D35B
        out 0xed, al                             ; D35E
        in al, 0x80                              ; D360  port 80h: POST diagnostic code
        inc al                                   ; D362
        out 0x80, al                             ; D364  port 80h: POST diagnostic code
