        push ax                                  ; D368
        or al, 0xc                               ; D369
        out 0x61, al                             ; D36B  port 61h: port B (speaker/parity/refresh)
        test al, 0xc0                            ; D36D
        pushf                                    ; D36F
        test byte [cs:0xaf45], 0x20              ; D370
        je short loc_D38D                        ; D376
        popf                                     ; D378
        jne short loc_D38D                       ; D379
        mov al, 0xb                              ; D37B
        out 0xa0, al                             ; D37D  port A0h: PIC2 command
        out 0xed, al                             ; D37F
        in al, 0xa0                              ; D381  port A0h: PIC2 command
