        mov si, 0xd426                           ; D385
        je short loc_D39A                        ; D388
        pop ax                                   ; D38A
        jmp short loc_D3F9                       ; D38B

loc_D38D:
        popf                                     ; D38D
        pop ax                                   ; D38E
        je short loc_D3F9                        ; D38F
        push ax                                  ; D391
        mov si, 0xd416                           ; D392
        js short loc_D39A                        ; D395
        mov si, 0xd404                           ; D397

loc_D39A:
        db 0xE8, 0xCE, 0xE4                      ; D39A  call print_string_cs_si
        call print_inline_msg                    ; D39D
; [data] string
