        call print_hex_word                      ; D3B2
        mov al, 0x3a                             ; D3B5
        db 0xE8, 0xA5, 0xE4                      ; D3B7  call print_char_al_int10
        mov ax, word [bp + 2]                    ; D3BA
        call print_hex_word                      ; D3BD
