; [data] inline message for print_inline_msg
        db 0x2E, 0x0D, 0x0A, 0x20, 0x54, 0x79, 0x70, 0x65, 0x20, 0x28, 0x53, 0x29, 0x68, 0x75, 0x74, 0x20 ; D3C3 ... Type (S)hut 
        db 0x6F, 0x66, 0x66, 0x20, 0x4E, 0x4D, 0x49, 0x2C, 0x00 ; D3D3 off NMI,.
        mov si, 0xd7d1                           ; D3DC
        call wait_key_from_list                  ; D3DF
        db 0xE8, 0x83, 0xE4                      ; D3E2  call print_crlf
        cmp al, 0x52                             ; D3E5
        jne short loc_D3EC                       ; D3E7
        db 0xE9, 0x6F, 0x0C                      ; D3E9  jmp post_entry

loc_D3EC:
        cmp al, 0x53                             ; D3EC
        pop ax                                   ; D3EE
        jne short loc_D3F3                       ; D3EF
        or al, 0xc                               ; D3F1

loc_D3F3:
