        out 0x61, al                             ; D3FB  port 61h: port B (speaker/parity/refresh)
        call cmos_read_shutdown_byte             ; D3FD
        pop si                                   ; D400
        pop ax                                   ; D401
        pop bp                                   ; D402
        iret                                     ; D403

; '\r\nI/O card parity' (NMI message).
msg_io_card_parity:
; [data] string
        db 0x0D, 0x0A, 0x49, 0x2F, 0x4F, 0x20, 0x63, 0x61, 0x72, 0x64, 0x20, 0x70, 0x61, 0x72, 0x69, 0x74 ; D404 ..I/O card parit
        db 0x79, 0x00 ; D414 y.

