        push ax                                  ; D43E

loc_D43F:
        mov al, byte [cs:si]                     ; D43F
        db 0x0A, 0xC0                            ; D442  or al, al
        je short loc_D44C                        ; D444
        db 0xE8, 0x16, 0xE4                      ; D446  call print_char_al_int10
        inc si                                   ; D449
        loop loc_D43F                            ; D44A

loc_D44C:
