parity_check_port61:
        push dx                                  ; D44E
        mov dx, 0x61                             ; D44F
        out 0xed, al                             ; D452
        in al, dx                                ; D454
        xchg al, ah                              ; D455
        call speaker_toggle                      ; D457
        and ah, 0xc0                             ; D45A
        shr ah, 1                                ; D45D
        shr ah, 1                                ; D45F
        shr ah, 1                                ; D461
        shr ah, 1                                ; D463
        db 0x0A, 0xC4                            ; D465  or al, ah
        out 0xed, al                             ; D467
        out dx, al                               ; D469
        test ah, 0xc                             ; D46A
        pop dx                                   ; D46D
        ret                                      ; D46E

