loc_D49E:
        ret                                      ; D49E

; 0000, 7C00:0000 boot far pointer, 0040 BDA segment.
zero_segment_words:
; [data] zero_segment_words
        db 0x00, 0x00 ; D49F ..

; Far pointer 0000:7C00 - INT 19h jumps through it into the loaded boot sector (F000:792F).
bootsector_farptr:
