        mov byte [bda.poll_counter], al          ; DA96  bda.poll_counter
        pop ax                                   ; DA99
        mov byte [bda.poll_counter + 1], al      ; DA9A  bda.poll_counter+1
        pop ds                                   ; DA9D
        push edx                                 ; DA9E
        push ecx                                 ; DAA0
        push eax                                 ; DAA2
        push ebx                                 ; DAA4
        mov eax, 1                               ; DAA6
        cpuid                                    ; DAAC
        and al, 0xf0                             ; DAAE
        cmp ax, 0x430                            ; DAB0
        pop ebx                                  ; DAB3
        pop eax                                  ; DAB5
        pop ecx                                  ; DAB7
        pop edx                                  ; DAB9
        db 0x75, 0x08                            ; DABB  jne loc_DAC5
        cmp al, 0x3e                             ; DABD
        db 0x75, 0x04                            ; DABF  jne loc_DAC5
        db 0x81, 0xC3, 0x03, 0x00                ; DAC1  add bx, 3

loc_DAC5:
        db 0x2E, 0x8B, 0xB7, 0x01, 0x00          ; DAC5  mov si, word ptr cs:[bx + 1]
        db 0xE8, 0x9E, 0xDD                      ; DACA  call print_string_cs_si
        db 0xE8, 0x39, 0xF8                      ; DACD  call print_inline_msg
; [data] string
; [data] inline message for print_inline_msg
        db 0x20, 0x4D, 0x68, 0x7A, 0x00 ; DAD0  Mhz.

loc_DAD5:
        db 0xE8, 0x31, 0xF8                      ; DAD5  call print_inline_msg
; [data] string
; [data] inline message for print_inline_msg
        db 0x0D, 0x0A, 0x0D, 0x0A, 0x00 ; DAD8 .....
        ret                                      ; DADD
; [data] string
        db 0x6F, 0x76, 0x65, 0x72, 0x20, 0x31, 0x30, 0x30, 0x00, 0x31, 0x30, 0x30, 0x00, 0x37, 0x35, 0x00 ; DADE over 100.100.75.
        db 0x36, 0x36, 0x00, 0x35, 0x30, 0x00, 0x34, 0x30, 0x00, 0x33, 0x33, 0x00, 0x32, 0x35, 0x00, 0x32 ; DAEE 66.50.40.33.25.2
        db 0x30, 0x00, 0x31, 0x36, 0x00, 0x75, 0x6E, 0x64, 0x65, 0x72, 0x20, 0x31, 0x36, 0x00, 0x69, 0xDE ; DAFE 0.16.under 16.i.
        db 0xDA, 0x55, 0xE7, 0xDA, 0x3E, 0xEB, 0xDA, 0x39, 0xEE, 0xDA, 0x2C, 0xF1, 0xDA, 0x24, 0xF4, 0xDA ; DB0E .U..>..9..,..$..
        db 0x20, 0xF7, 0xDA, 0x16, 0xFA, 0xDA, 0x12, 0xFD, 0xDA, 0x0E, 0x00, 0xDB, 0x00, 0x03, 0xDB ; DB1E  ..............

; PIT channel 0 mode 2, count 0 (18.2 Hz system tick).
pit_ch0_init_mode2:
        cli                                      ; DB2D
        mov al, 0x34                             ; DB2E
        out 0x43, al                             ; DB30  port 43h: PIT control
        out 0xed, al                             ; DB32
        mov al, 0                                ; DB34
        out 0x40, al                             ; DB36  port 40h: PIT ch0 (timer tick)
        out 0xed, al                             ; DB38
        out 0x40, al                             ; DB3A  port 40h: PIT ch0 (timer tick)
        sti                                      ; DB3C
        cld                                      ; DB3D
        mov cx, 0xc                              ; DB3E
        mov ax, 0x7c0                            ; DB41
        mov es, ax                               ; DB44
        db 0x33, 0xFF                            ; DB46  xor di, di
        mov ds, word [cs:0xfff3]                 ; DB48
        mov si, 0xda2a                           ; DB4D  -> cpu_speed_loop_retf
        rep movsb                                ; DB50
        db 0x33, 0xD2                            ; DB52  xor dx, dx
        mov bx, 0xff                             ; DB54
        mov cx, 0x3e8                            ; DB57
        cli                                      ; DB5A
        mov al, 0                                ; DB5B
        out 0x43, al                             ; DB5D  port 43h: PIT control
        in al, 0x40                              ; DB5F  port 40h: PIT ch0 (timer tick)
        db 0x8A, 0xE0                            ; DB61  mov ah, al
        in al, 0x40                              ; DB63  port 40h: PIT ch0 (timer tick)
        xchg al, ah                              ; DB65
        db 0x8B, 0xF8                            ; DB67  mov di, ax

; Far call 07C0:0000 - jumps into the loaded boot sector.
boot_call_bootsector_a:
        db 0x9A, 0x00, 0x00, 0xC0, 0x07          ; DB69  lcall 07C0:0000 ; far call outside module
        in al, 0x40                              ; DB6E  port 40h: PIT ch0 (timer tick)
        db 0x8A, 0xE0                            ; DB70  mov ah, al
        in al, 0x40                              ; DB72  port 40h: PIT ch0 (timer tick)
        xchg al, ah                              ; DB74
        db 0x2B, 0xF8                            ; DB76  sub di, ax
        push di                                  ; DB78
        mov cx, 0x18                             ; DB79
        mov ax, 0x7c0                            ; DB7C
        mov es, ax                               ; DB7F
        db 0x33, 0xFF                            ; DB81  xor di, di
        mov ds, word [cs:0xfff3]                 ; DB83
        mov si, 0xda36                           ; DB88  -> cpu_speed_div_loop_retf
        rep movsb                                ; DB8B
        db 0x33, 0xD2                            ; DB8D  xor dx, dx
        mov bx, 0xff                             ; DB8F
        mov cx, 0x3e8                            ; DB92
        mov al, 0                                ; DB95
        out 0x43, al                             ; DB97  port 43h: PIT control
        in al, 0x40                              ; DB99  port 40h: PIT ch0 (timer tick)
        db 0x8A, 0xE0                            ; DB9B  mov ah, al
        in al, 0x40                              ; DB9D  port 40h: PIT ch0 (timer tick)
        xchg al, ah                              ; DB9F
        db 0x8B, 0xF0                            ; DBA1  mov si, ax
        db 0x9A, 0x00, 0x00, 0xC0, 0x07          ; DBA3  lcall 07C0:0000 ; far call outside module
        in al, 0x40                              ; DBA8  port 40h: PIT ch0 (timer tick)
        db 0x8A, 0xE0                            ; DBAA  mov ah, al
        in al, 0x40                              ; DBAC  port 40h: PIT ch0 (timer tick)
        xchg al, ah                              ; DBAE
        sti                                      ; DBB0
        pop di                                   ; DBB1
        db 0x2B, 0xF0                            ; DBB2  sub si, ax
        db 0x2B, 0xF7                            ; DBB4  sub si, di
        db 0x8B, 0xC6                            ; DBB6  mov ax, si
        mov dx, 0x20bd                           ; DBB8
        mul dx                                   ; DBBB
        mov bx, 0x2710                           ; DBBD
        div bx                                   ; DBC0
        db 0x8B, 0xD8                            ; DBC2  mov bx, ax
        mov ax, 0x86a0                           ; DBC4
        mov dx, 1                                ; DBC7
        div bx                                   ; DBCA
        ret                                      ; DBCC

; Walk (threshold,value) byte pairs at DC09 to pick a value for chipset register 300h from AL.
chipset_speed_table_program:
        mov bx, 0xdc09                           ; DBCD

loc_DBD0:
        db 0x2E, 0x3A, 0x87, 0x00, 0x00          ; DBD0  cmp al, byte ptr cs:[bx]
        db 0x73, 0x0C                            ; DBD5  jae loc_DBE3
        db 0x81, 0xC3, 0x02, 0x00                ; DBD7  add bx, 2
        db 0x2E, 0x80, 0xBF, 0x00, 0x00, 0x00    ; DBDB  cmp byte ptr cs:[bx], 0
        db 0x75, 0xED                            ; DBE1  jne loc_DBD0

loc_DBE3:
        db 0x2E, 0x8A, 0x8F, 0x01, 0x00          ; DBE3  mov cl, byte ptr cs:[bx + 1]
        mov dx, 0x24                             ; DBE8
        mov ax, 0x300                            ; DBEB
        out dx, ax                               ; DBEE
        out 0xed, al                             ; DBEF
        mov dx, 0x26                             ; DBF1
        in ax, dx                                ; DBF4
        and al, 0xf8                             ; DBF5
        db 0x0A, 0xC1                            ; DBF7  or al, cl
        push ax                                  ; DBF9
        mov dx, 0x24                             ; DBFA
        mov ax, 0x300                            ; DBFD
        out dx, ax                               ; DC00
        out 0xed, al                             ; DC01
        mov dx, 0x26                             ; DC03
        pop ax                                   ; DC06
        out dx, ax                               ; DC07
        ret                                      ; DC08

; Seven word pairs 2C07h 2407h 2006h 1604h 1203h 0E02h 0002h - cursor start/end per character height (best guess).
cursor_shape_table:
