; Default handler for unused IRQs: sends EOI to both PICs, IRET.
int_default_irq_handler:
        db 0xE9, 0x39, 0xD6                      ; FF33  jmp int_default_handler
        times 13 db 0xFF                     ; FF36 fill

; Second default IRQ handler variant.
int_default_irq_handler_2:
        test byte [cs:0xaf45], 0x20              ; FF43
        je short int_default_irq_handler         ; FF49
        push ax                                  ; FF4B
        mov al, 0x20                             ; FF4C
        out 0xa0, al                             ; FF4E  port A0h: PIC2 command
        out 0x20, al                             ; FF50  port 20h: PIC1 command
        pop ax                                   ; FF52

; Classic IBM FF53: IRET stub for INT 1Bh/1Ch etc.
int_dummy_iret:
        iret                                     ; FF53

; Classic IBM INT 05h (print screen) entry.
int05_print_screen_entry:
        db 0xE9, 0x10, 0xD9                      ; FF54  jmp loc_D867
        db 0xFF, 0xFF, 0xFF ; FF57 ...

; call sub_D1C6; retf (Phoenix far-callable stub).
fixed_entry_FF5A:
        db 0xE8, 0x69, 0xD2                      ; FF5A  call delay_100_refresh
        retf                                     ; FF5D
        db 0xFF, 0xFF ; FF5E ..

; call sub_8695; retf.
fixed_entry_FF60:
        db 0xE8, 0x32, 0x87                      ; FF60  call int15_4F_setup_hotkey_check
        retf                                     ; FF63

