rom_option_table_far_ptr:
; [data] rom_option_table_far_ptr
        db 0xFB, 0xAC, 0x00, 0xF0 ; FF64 ....

; ret.
ret_FF68:
        ret                                      ; FF68
        times 14 db 0xFF                     ; FF69 fill
; [data] fill
        db 0xFF ; FF77 .

; call sub_8656; retf.
fixed_entry_FF77:
        db 0xE8, 0xDC, 0x86                      ; FF78  call cpu_speed_get_level
        retf                                     ; FF7B

; call sub_8619; retf.
fixed_entry_FF7C:
        db 0xE8, 0x9A, 0x86                      ; FF7C  call cpu_speed_set_level
        retf                                     ; FF7F

; 2 bytes before fixed_entry_FF82.
bytes_FF80:
; [data] bytes_FF80
        db 0x86, 0x03 ; FF80 ..

; call sub_CE49; retf.
fixed_entry_FF82:
        db 0xE8, 0xC4, 0xCE                      ; FF82  call int15_24_a20_gate_service
        retf                                     ; FF85
; [data] fill
        times 54 db 0xFF                     ; FF86 fill
        db 0x30, 0x30, 0x37, 0x37, 0x2F, 0x2F, 0x30, 0x30, 0x36, 0x36, 0x2F, 0x2F, 0x39, 0x39, 0x34, 0x34 ; FFBC 0077//0066//9944
