        db 0x00, 0x00, 0xD1 ; FFEC ...

; Byte adjusted by hd_autodetect_patch_table so that the shadow copy of F000 keeps its 8-bit checksum after the disk table is patched.
rom_checksum_adjust_byte:
        db 0x00 ; FFEF .

; CPU reset lands here (F000:FFF0). Far jump to POST entry.
reset_vector:
        jmp 0xF000:0xE05B                        ; FFF0

; ASCII release date 'MM/DD/YY' (Phoenix placeholder 04/19/90).
bios_date:
; [data] release date
; [data] string
        db 0x30, 0x34, 0x2F, 0x31, 0x39, 0x2F, 0x39, 0x30 ; FFF5 04/19/90
; [data] unused byte, model byte FCh, checksum byte
        db 0xFF ; FFFD .

; FCh = IBM AT class
model_byte:
        db 0xFC, 0x00 ; FFFE ..
